-- Desktop decisions for this machine.
--
-- Generated by bin/ms from canonical/desktop/hypr/. Do not edit by hand:
-- edits are reported by `ms diff` and overwritten by `ms project`.
--
-- This module is loaded LAST by hyprland.lua, so what it sets overrides the
-- CachyOS template. The template files under config/ are left pristine, which
-- keeps "what CachyOS ships" and "what we decided" separable.

hl.config({
    input = {
        kb_layout = "gb",
    },
})

hl.monitor({
    output   = MONITOR1,
    mode     = "3840x2400@120",
    position = "auto",
    scale    = "auto",
})

-- Session programs this repository added. The template's own list lives in
-- config/autostart.lua and stays untouched; this handler runs alongside it.
hl.on("hyprland.start", function ()
    -- The firewall's prompt and tray (canonical/tooling/opensnitch.md). The
    -- delay is the one its .desktop file asks for: the tray must be up first.
    hl.exec_cmd("sh -c 'sleep 3; exec opensnitch-ui'")
end)
